window.codexAvatar = function(seed) {
  let hash = 0;
  for (let index = 0; index < seed.length; index += 1) hash = (hash * 31 + seed.charCodeAt(index)) % 2147483647;
  const avatar = window.CODEX_AVATARS[hash % window.CODEX_AVATARS.length];
  return '<picture><source media="(prefers-color-scheme: dark)" srcset="data:image/svg+xml,' + encodeURIComponent(avatar.dark) + '"><img alt="" draggable="false" src="data:image/svg+xml,' + encodeURIComponent(avatar.light) + '"></picture>';
};
